mapper.select:
SELECT id, wallet_id, user_id, balance, frozen_amount, create_time
FROM virtual_wallet
WHERE user_id = #{userId}

mapper.update:
UPDATE virtual_wallet
SET balance    = balance - #{amount},
    update_time = NOW()
WHERE user_id = #{userId}
  AND balance >= #{amount}

UPDATE virtual_wallet
SET balance    = balance - #{amount},
    update_time = NOW()
WHERE user_id = #{userId}
  AND balance - frozen_amount >= #{amount}
